sql.where:
t.deleted = 0

    AND t.scenario_id = #{req.scenarioId}


    AND t.source_res_id = #{req.sourceResId}


    AND t.res_code LIKE CONCAT('%', #{req.resCode}, '%')


    AND t.res_name LIKE CONCAT('%', #{req.resName}, '%')


    AND t.res_type = #{req.resType}


    AND t.plant_id = #{req.plantId}


    AND t.workshop_id = #{req.workshopId}


    AND t.wc_id = #{req.wcId}


    AND t.shift_id = #{req.shiftId}


    AND t.work_date BETWEEN #{req.workDate[0]} AND #{req.workDate[1]}


    AND t.snapshot_time BETWEEN #{req.snapshotTime[0]} AND #{req.snapshotTime[1]}
